-- パーソナルコーチ (β) の候補食品に、区分・量の選択肢などの列を足す。
-- 追加のみ: 列の追加、コメントの更新、66品の upsert、設計外の旧候補は is_active=false（行は消さない）。
-- 設計: docs/coach/personal_coach_design.md
-- 前提: 20261004120000_coach_food_candidates.sql は本番適用済み（version 20261007034452）。

begin;

alter table public.coach_food_candidates
  add column if not exists coach_role text
    check (coach_role is null or coach_role in ('staple', 'main', 'side', 'dairy', 'fruit')),
  add column if not exists coach_subrole text
    check (coach_subrole is null or coach_subrole in (
      'grain', 'meat', 'fish', 'egg', 'soy', 'vegetable', 'mushroom', 'potato',
      'milk', 'yogurt', 'cheese', 'fruit')),
  add column if not exists is_green_yellow_vegetable boolean not null default false,
  add column if not exists is_starchy_side boolean not null default false,
  add column if not exists is_bread_or_noodle boolean not null default false,
  add column if not exists portion_options jsonb not null default '[]'::jsonb
    check (jsonb_typeof(portion_options) = 'array'),
  add column if not exists portion_source text
    check (portion_source is null or char_length(portion_source) between 1 and 200),
  add column if not exists is_active boolean not null default true;

comment on table public.coach_food_candidates is
  'パーソナルコーチ (β) の食事候補。画面の名前・区分・量の選択肢。栄養値は official_foods を参照し、この表には写さない。';
comment on column public.coach_food_candidates.coach_role is
  '主食 staple／主菜 main／副菜 side／乳製品 dairy／果物 fruit。';
comment on column public.coach_food_candidates.is_green_yellow_vegetable is
  '厚労省 健健発0804第1号 別表「緑黄色野菜」に載る食品。一食の副菜2品のうち1品以上はこれ。';
comment on column public.coach_food_candidates.is_starchy_side is
  'いも・かぼちゃ・とうもろこし。副菜2品に同時に入れない。';
comment on column public.coach_food_candidates.is_bread_or_noodle is
  'パン・麺。焼き魚・刺身と合わせない。';
comment on column public.coach_food_candidates.portion_options is
  '選べる量 [{tier: light|standard|hearty|any, label, grams}]。案の量はこの中からだけ選ぶ。';
comment on column public.coach_food_candidates.is_active is
  'false の行は候補に使わない（行は消さない）。';
comment on table public.coach_proposal_logs is
  'パーソナルコーチ (β) の提案。提案内容、登録したか、日時だけを残す。';

-- 設計の66品にない旧候補は消さずに止める。
update public.coach_food_candidates
set is_active = false
where food_code not in (
'01088', '01085', '01111', '01026', '01034', '01039', '01128', '11288', '11225', '11222', '11229',
